import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import { aciReportData, verifyAciAttestation } from './aci.js';
import { decryptChunk, fromHex, toHex } from './crypto.js';
import { computeWorkloadId, recoverReceiptSigner } from './receipt.js';

// Fixed vectors generated by @noble/secp256k1 2.3.0, independently of the
// installed implementation. These catch matching sign/verify regressions.
const legacy = JSON.parse(readFileSync(
  new URL('./test-fixtures/secp256k1-v2.json', import.meta.url), 'utf8'
));

describe('secp256k1 v2 wire compatibility', () => {
  it('decrypts v2 ECDH/HKDF/AES-GCM ciphertext', async () => {
    expect(await decryptChunk(fromHex(legacy.key), legacy.cipher)).toBe(legacy.text);
  });

  it.each([
    { kind: 'low-S', signature: legacy.endorsement },
    { kind: 'high-S', signature: legacy.highS },
  ])('verifies a v2 $kind keyset endorsement', async ({ signature }) => {
    const nonce = 'a1'.repeat(32);
    const workloadId = computeWorkloadId(legacy.keyset.workload_identity.public_key);
    const reportData = aciReportData(workloadId, legacy.digest, nonce);
    const quote = new Uint8Array(632);
    quote[0] = 4;
    quote[4] = 0x81;
    quote.set(reportData, 568);
    const result = await verifyAciAttestation({
      api_version: 'aci/1',
      workload_id: workloadId,
      workload_keyset_digest: legacy.digest,
      attestation: {
        vendor: 'test-gateway',
        tee_type: 'tdx',
        workload_keyset: legacy.keyset,
        report_data: toHex(reportData),
        keyset_endorsement: { algo: 'ecdsa-secp256k1', value: signature },
        evidence: { quote: toHex(quote) },
      },
    }, nonce, { requireDcap: false });
    expect(result.checks.find((check) => check.name === 'keyset_endorsement')?.ok).toBe(true);
  });

  it.each([0, 27])('recovers a v2 EIP-191 signer with recovery offset %i', (offset) => {
    const recovery = Number.parseInt(legacy.signature.slice(-2), 16) + offset;
    const signature = legacy.signature.slice(0, -2) + recovery.toString(16).padStart(2, '0');
    expect(recoverReceiptSigner(legacy.text, signature)).toBe(legacy.address);
    expect(recoverReceiptSigner(legacy.text + 'changed', signature)).not.toBe(legacy.address);
  });
});
